};
}

export interface HyperspeedProps {
effectOptions?: HyperspeedOptions;
className?: string;
}

const DEFAULT_OPTIONS: HyperspeedOptions = {
onSpeedUp: () => { },
onSlowDown: () => { },
distortion: 'turbulentDistortion',
length: 400,
